// READ ONLY. Returns the latest emails sent to ONE plus address of the shared test inbox.
// Set INBOX once (the QR code localization Gmail). Only <local>+<tag>@<domain> addresses are allowed:
// the flow never reads mail sent to the bare inbox (real mail), only test sign-ups.
const INBOX = 'SET_ME@gmail.com';
const q = $input.first().json.query || {};
const to = String(q.to || '').trim().toLowerCase();
const [local, domain] = INBOX.toLowerCase().split('@');
const ok = new RegExp('^' + local.replace(/[.]/g, '\\.') + '\\+[a-z0-9._-]{1,60}@' + domain.replace(/[.]/g, '\\.') + '$');
if (INBOX.startsWith('SET_ME')) throw new Error('Params: INBOX is not set yet');
if (!ok.test(to)) throw new Error('Only ' + local + '+<tag>@' + domain + ' addresses can be read');
const since = q.since ? new Date(q.since) : new Date(Date.now() - 60 * 60 * 1000);
if (isNaN(since)) throw new Error('since must be an ISO date');
return [{ json: { inbox: INBOX, to, query: 'to:' + to, since: since.toISOString() } }];

// One item: the address, how many emails, and per email the subject, sender, date, the
// codes and links found (to verify the account) and the first 4 000 characters of text.
const p = $('Params').first().json;
const msgs = $input.all().map(i => i.json).filter(m => m && m.id);
const out = msgs.map(m => {
  const text = String(m.text || '').slice(0, 4000);
  const links = [...new Set((String(m.html || '') + ' ' + text).match(/https:\/\/[^\s"'<>)]+/g) || [])].slice(0, 15);
  const codes = [...new Set(((m.subject || '') + ' ' + text).match(/\b\d{4,8}\b/g) || [])].slice(0, 5);
  return { id: m.id, date: m.date, from: m.from && m.from.text, to: m.to && m.to.text,
           subject: m.subject, codes, links, text };
}).sort((a, b) => String(b.date).localeCompare(String(a.date)));
return [{ json: { inbox: p.inbox, to: p.to, since: p.since, count: out.length, messages: out } }];
